(async () => {
  const pages = figma.root.children;
  const mediaPage = pages.find(p => p.name.includes("04 · Media"));
  if (!mediaPage) return "Media page not found";

  const nodes = mediaPage.findAll(n => n.type === "COMPONENT" || n.type === "COMPONENT_SET");
  const result = {};
  for (const n of nodes) {
    if (n.name.startsWith("Icon_") || n.name.startsWith("Logo_") || n.name.startsWith("Decor_")) {
      result[n.name] = { id: n.id, width: n.width, height: n.height };
    }
  }
  return result;
})()

