    navFrame.counterAxisAlignItems = "CENTER";

    const navItems = ["Home", "Recipes", "Blog", "Contact", "About us"];
    navItems.forEach(item => {
      const txt = figma.createText();
      txt.characters = item;
      txt.fontSize = 16;
      txt.fontName = { family: "Inter", style: item === activeNav ? "Semi Bold" : "Medium" };
      txt.fills = [{ type: "SOLID", color: item === activeNav ? { r: 1, g: 0.4, b: 0.4 } : { r: 0, g: 0, b: 0 } }];
