  // Let's recursively search for nodes in a frame that match a specific text character or name
  function findNodesInFrame(frame) {
    const list = [];
    function traverse(node) {
      list.push({ id: node.id, name: node.name, type: node.type, characters: node.type === "TEXT" ? node.characters : undefined });
      if (node.children) {
        node.children.forEach(traverse);
      }
    }
    traverse(frame);
    return list;
  }

