(async () => {
  const f01 = figma.getNodeById("11:2");
  const children = [];
  function printChildren(node, level = 0) {
    if (!node) return;
    children.push("  ".repeat(level) + node.name + " (" + node.type + ")");
    if (node.children) {
      node.children.forEach(c => printChildren(c, level + 1));
    }
  }
  // Print children of f01 up to 2 levels deep
  if (f01 && f01.children) {
    f01.children.forEach(c => {
      children.push(c.name + " (" + c.type + ")");
      if (c.children) {
        c.children.forEach(gc => {
          children.push("  " + gc.name + " (" + gc.type + ")");
        });
      }
    });
  }
  return children.slice(0, 100);
})()

