(async () => {
  const pages = figma.root.children;
  const workspace = pages.find(p => p.name.includes("03 · Workspace"));
  const mediaPage = pages.find(p => p.name.includes("04 · Media"));
  await figma.setCurrentPageAsync(workspace);

  // Clear workspace
  workspace.children.forEach(c => c.remove());

  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  await figma.loadFontAsync({ family: "Inter", style: "Medium" });
  await figma.loadFontAsync({ family: "Inter", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Inter", style: "Bold" });

  const mediaMap = {};
  if (mediaPage) {
    mediaPage.findAll(n => n.type === "COMPONENT" || n.type === "COMPONENT_SET").forEach(s => {
      mediaMap[s.name] = s;
    });
  }

  function getInst(name) {
    if (mediaMap[name]) {
      return mediaMap[name].createInstance();
    }
    const frame = figma.createFrame();
    frame.name = name;
    frame.resize(100, 100);
    return frame;
  }

  function createHeader(activeNav = "Home") {
    const header = figma.createFrame();
    header.name = "Header";
    header.resize(1280, 80);
    header.fills = [];
    header.layoutMode = "HORIZONTAL";
    header.primaryAxisAlignItems = "SPACE_BETWEEN";
    header.counterAxisAlignItems = "CENTER";

    header.appendChild(getInst("Logo_Foodieland"));

    const navFrame = figma.createFrame();
    navFrame.name = "Navigation";
    navFrame.layoutMode = "HORIZONTAL";
    navFrame.itemSpacing = 40;
    navFrame.fills = [];
    navFrame.counterAxisAlignItems = "CENTER";

    const navItems = ["Home", "Recipes", "Blog", "Contact", "About us"];
    navItems.forEach(item => {
      const txt = figma.createText();
      txt.name = item;
      txt.characters = item;
      txt.fontSize = 16;
      txt.fontName = { family: "Inter", style: item === activeNav ? "Semi Bold" : "Medium" };
      txt.fills = [{ type: "SOLID", color: item === activeNav ? { r: 1, g: 0.4, b: 0.4 } : { r: 0, g: 0, b: 0 } }];
      navFrame.appendChild(txt);
    });
    header.appendChild(navFrame);

    const socialFrame = figma.createFrame();
    socialFrame.name = "Social Links";
    socialFrame.layoutMode = "HORIZONTAL";
    socialFrame.itemSpacing = 24;
    socialFrame.fills = [];
    socialFrame.counterAxisAlignItems = "CENTER";

    ["Logo_Facebook", "Logo_Twitter", "Logo_Instagram"].forEach(sName => {
      socialFrame.appendChild(getInst(sName));
    });
    header.appendChild(socialFrame);

    return header;
  }

  function createFooter() {
    const footer = figma.createFrame();
    footer.name = "Footer";
    footer.resize(1280, 160);
    footer.fills = [];
    footer.layoutMode = "VERTICAL";
    footer.itemSpacing = 40;

    const topRow = figma.createFrame();
    topRow.name = "Top Row";
    topRow.resize(1280, 50);
    topRow.layoutMode = "HORIZONTAL";
